html:
{%- set pmo = pmo_project_status(doc.name) -%}
{#- fecha ISO directa (sin format_date): evita el bug get_locale_value en sesiones sin idioma (PDF/jobs) -#}
{%- macro d(x) -%}{% if x %}{{ x }}{% else %}—{% endif %}{%- endmacro -%}
{%- macro slip(x) -%}{% if x is none %}—{% else %}{{ x }} d{% endif %}{%- endmacro -%}
{%- set health_color = {'on_track':'#1f9d55','at_risk':'#d97706','deviated':'#c02b2b'} -%}
<div class="pmo-ps">
<style>
.pmo-ps{font-family:'Helvetica Neue',Arial,sans-serif;color:#222;font-size:12px}
.pmo-ps h1{font-size:20px;margin:0 0 2px}
.pmo-ps .muted{color:#666}
.pmo-ps .band{border-top:3px solid #2b3a67;padding-top:8px;margin-bottom:12px;display:flex;justify-content:space-between;align-items:flex-start}
.pmo-ps .health{font-weight:bold;padding:3px 10px;border-radius:12px;color:#fff;font-size:12px}
.pmo-ps .cards{display:flex;flex-wrap:wrap;gap:8px;margin:10px 0}
.pmo-ps .card{border:1px solid #e2e2e2;border-radius:6px;padding:8px 10px;min-width:150px;flex:1}
.pmo-ps .card .lbl{color:#666;font-size:10px;text-transform:uppercase;letter-spacing:.03em}
.pmo-ps .card .val{font-size:15px;font-weight:bold;margin-top:2px}
.pmo-ps .bad{color:#c02b2b}.pmo-ps .ok{color:#1f9d55}
.pmo-ps .bar{background:#eee;border-radius:5px;height:10px;overflow:hidden;margin-top:4px}
.pmo-ps .bar > span{display:block;height:100%;background:#2b3a67}
.pmo-ps h2{font-size:13px;border-bottom:1px solid #ddd;padding-bottom:3px;margin:16px 0 6px}
.pmo-ps table{width:100%;border-collapse:collapse;font-size:11px}
.pmo-ps th,.pmo-ps td{border-bottom:1px solid #eee;padding:5px 6px;text-align:left}
.pmo-ps th{background:#f4f5f8;color:#333}
.pmo-ps td.num{text-align:right}
.pmo-ps .counts{margin:6px 0;color:#444}
.pmo-ps .note{color:#666;font-style:italic;margin-top:6px;font-size:10px}

.pmo-ps .grange{color:#666;font-size:10px;margin:2px 0 4px}
.pmo-ps table.gantt{width:100%;border-collapse:collapse;table-layout:fixed;font-size:10px}
.pmo-ps table.gantt td{border-bottom:1px solid #f2f2f2;padding:3px 6px;vertical-align:middle}
.pmo-ps table.gantt td.gname{width:34%;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.pmo-ps table.gantt td.glane{width:66%}
.pmo-ps .gtrack{position:relative;height:13px;background:#f4f5f8;border-radius:2px}
.pmo-ps .gbar{position:absolute;top:2px;height:9px;background:#2b3a67;border-radius:2px}
.pmo-ps .gbar.grp{background:#8a93ad;height:5px;top:4px}
.pmo-ps .gfill{height:100%;background:#1f9d55;border-radius:2px}
.pmo-ps .gms{position:absolute;top:2px;width:9px;height:9px;background:#c02b2b;transform:rotate(45deg)}
</style>

<div class="band">
  <div>
    <h1>{{ doc.project_name or doc.name }}</h1>
    <div class="muted">
      {{ doc.get_formatted('status') }}
      {%- if doc.company %} · {{ doc.company }}{% endif %}
      {%- if doc.customer %} · {{ frappe.db.get_value('Customer', doc.customer, 'customer_name') or doc.customer }}{% endif %}
    </div>
    <div class="muted">{{ _("Cutoff date (Status Date):") }} <b>{{ d(pmo.status_date) }}</b></div>
  </div>
  <div class="health" style="background:{{ health_color.get(pmo.health_key, '#666') }}">{{ _(pmo.health) }}</div>
</div>

<h2>{{ _("Executive summary") }}</h2>
<div class="cards">
  <div class="card">
    <div class="lbl">{{ _("Progress") }}</div>
    <div class="val">{{ (doc.percent_complete or 0) | round(0) | int }}%</div>
    <div class="bar"><span style="width:{{ (doc.percent_complete or 0) | round(0) | int }}%"></span></div>
  </div>
  <div class="card">
    <div class="lbl">{{ _("Baseline") }}</div>
    <div class="val">{% if pmo.baseline %}{{ d(pmo.baseline.expected_end_date) }}{% else %}— {{ _("no baseline") }}{% endif %}</div>
    <div class="muted">{{ _("Slip vs Baseline:") }} {{ slip(pmo.slip_baseline) }}</div>
  </div>
  <div class="card">
    <div class="lbl">{{ _("Current forecast (plan)") }}</div>
    <div class="val">{{ d(pmo.forecast_end) }}</div>
    <div class="muted">{{ _("Project planned end (ERPNext)") }}</div>
  </div>
  <div class="card">
    <div class="lbl">{{ _("Committed date") }}</div>
    <div class="val">{{ d(pmo.committed_end) }}</div>
    <div class="muted {% if (pmo.slip_committed or 0) > 0 %}bad{% endif %}">{{ _("Slip vs commitment:") }} {{ slip(pmo.slip_committed) }}</div>
  </div>
</div>
<div class="cards">
  <div class="card"><div class="lbl">{{ _("Overdue tasks at cutoff") }}</div><div class="val {% if pmo.overdue %}bad{% endif %}">{{ pmo.overdue }}</div></div>
  <div class="card"><div class="lbl">{{ _("Forecast exceeds commitment") }}</div><div class="val {% if pmo.forecast_exceeds %}bad{% endif %}">{{ pmo.forecast_exceeds }}</div></div>
  <div class="card">
    <div class="lbl">{{ _("Effort (hours)") }}</div>
    <div class="val">{{ pmo.actual_hours }} / {{ pmo.planned_hours }}</div>
    <div class="muted">{{ _("% consumed:") }} {% if pmo.pct_consumed is none %}—{% else %}{{ pmo.pct_consumed }}%{% endif %}</div>
  </div>
</div>
<div class="counts">{{ _("Tasks:") }} <b>{{ pmo.counts.total }}</b> · {{ _("completed") }} {{ pmo.counts.completed }} · {{ _("active") }} {{ pmo.counts.active }} · {{ _("overdue at cutoff") }} {{ pmo.counts.overdue_at_cutoff }}</div>

{% if pmo.gantt.tasks %}
<h2>{{ _("Schedule (Gantt)") }}</h2>
<div style="page-break-inside:avoid">
<p class="grange">{{ d(pmo.gantt.min_start) }} &rarr; {{ d(pmo.gantt.max_end) }}</p>
<table class="gantt">
{% for t in pmo.gantt.tasks %}
<tr>
<td class="gname" style="padding-left:{{ 6 + t.depth * 12 }}px">{% if t.is_milestone %}&#9670; {% endif %}{% if t.is_group %}<b>{{ t.subject }}</b>{% else %}{{ t.subject }}{% endif %}</td>
<td class="glane"><div class="gtrack">{% if t.offset_pct is not none %}{% if t.is_milestone %}<div class="gms" style="left:{{ t.offset_pct }}%"></div>{% else %}<div class="gbar {% if t.is_group %}grp{% endif %}" style="left:{{ t.offset_pct }}%;width:{{ t.width_pct }}%">{% if not t.is_group %}<div class="gfill" style="width:{{ t.progress }}%"></div>{% endif %}</div>{% endif %}{% endif %}</div></td>
</tr>
{% endfor %}
</table>
</div>
{% endif %}

{% if pmo.milestones %}
<h2>{{ _("Milestones") }}</h2>
<table>
  <thead><tr><th>{{ _("Milestone") }}</th><th>{{ _("End (Baseline)") }}</th><th>{{ _("End (Forecast)") }}</th><th class="num">{{ _("Slip") }}</th><th>{{ _("Overdue at cutoff") }}</th></tr></thead>
  <tbody>
  {% for m in pmo.milestones %}
    <tr>
      <td>{{ m.subject }}</td><td>{{ d(m.baseline_exp_end_date) }}</td><td>{{ d(m.current_exp_end_date) }}</td>
      <td class="num">{{ slip(m.slip_days) }}</td><td>{% if m.overdue_at_status_date %}{{ _("Yes") }}{% else %}—{% endif %}</td>
    </tr>
  {% endfor %}
  </tbody>
</table>
{% endif %}

<h2>{{ _("Tasks to evaluate (with deviation)") }}</h2>
{% if pmo.relevant_tasks %}
<table>
  <thead><tr><th>{{ _("Task") }}</th><th>{{ _("End (Baseline)") }}</th><th>{{ _("End (Forecast)") }}</th><th class="num">{{ _("Slip") }}</th><th>{{ _("Commitment") }}</th><th>{{ _("Overdue") }}</th></tr></thead>
  <tbody>
  {% for t in pmo.relevant_tasks %}
    <tr>
      <td>{% if t.is_milestone %}★ {% endif %}{{ t.subject }}</td>
      <td>{{ d(t.baseline_exp_end_date) }}</td>
      <td>{{ d(t.current_exp_end_date) }}</td>
      <td class="num {% if (t.slip_days or 0) > 0 %}bad{% endif %}">{{ slip(t.slip_days) }}</td>
      <td class="{% if t.exceeds_deadline %}bad{% endif %}">{{ d(t.pmo_deadline) }}</td>
      <td>{% if t.overdue_at_status_date %}{{ _("Yes") }}{% else %}—{% endif %}</td>
    </tr>
  {% endfor %}
  </tbody>
</table>
{% else %}
<div class="muted">{{ _("No tasks with relevant deviation at the cutoff date.") }}</div>
{% endif %}
{% if pmo.omitted_tasks %}
<div class="note">{{ _("{0} task(s) with baseline but without relevant deviation are not listed (of {1} with baseline).").format(pmo.omitted_tasks, pmo.total_baseline_tasks) }}</div>
{% endif %}
</div>
